      "sentence_id": 7
    },
    {
      "dsl": "unsettled(strength(\"utilization & age\") == \"moderate\")",
      "sentence_id": 7
    }
  ],
  "sentences": [
    {
      "id": 1,
      "text": "Revolving credit utilization is the most important driver of default risk, accounting for about 37% of the model's importance, with risk increasing as utilization rises."
    },
    {
      "id": 2,
      "text": "Number of past delinquencies is the second most important driver, with a strong effect that increases risk when delinquencies are present."
    },
    {
      "id": 3,
      "text": "Debt-to-income ratio is a third to fifth most important driver, with a weak to moderate effect that increases risk as the ratio goes up."
    },
    {
      "id": 4,
      "text": "Length of credit history is also a third to fifth most important driver, with a weak to moderate effect that decreases risk as history length increases."
    },
    {
      "id": 5,
      "text": "The effect of number of past delinquencies grows with revolving credit utilization."
    },
    {
      "id": 6,
      "text": "Number of recent credit inquiries, age, months at address, and number of dependents hardly matter to the model's predictions."
    },
    {
      "id": 7,
      "text": "The data do not settle whether annual income, or interactions between credit history length and recent inquiries, dependents, or delinquencies, represent moderate effects."
    }
  ]
}

